@startuml

class Product {
  + Name : string
  + Stock : int
}

class Customer {
  + Name : string
  + Address : string
  + VATnumber : string
  + HeadOfficeAddress : string
}

class Order {
  + OrderNumber : string
  + DeliveryAddress : string
  + PaidDate : date
  + ShippedDate : date
}

class OrderLine {
  + Quantity : int
  + ShippedQuantity : int
}

class Invoice {
  + InvoiceNumber : string
  + PaymentDate : date
}

class Delivery {
  + DeliveryNumber : string
  + Status : string
}

class DeliveryLine {
  + Status : string
}

class Warehouse {
  + Location : string
}

Customer "1" -- "*" Order : places
Customer "1" -- "*" Invoice : receives
Order "1" -- "1..*" OrderLine : consists of
Order "1" -- "0..1" Invoice : generates
Order "1" -- "0..*" Delivery : is shipped via
OrderLine "1" -- "0..*" DeliveryLine : is part of
Delivery "1" -- "1..*" DeliveryLine : contains
Product "1" -- "0..*" OrderLine : is ordered in
Product "0..*" -- "1..*" Warehouse : is stored in

@enduml

